  "messages": [
    {
      "role": "system",
      "content": "Anda adalah EKSAD System Analyst Agentic AI. Berikan respon presisi tanpa halusinasi."
    },
    {
      "role": "user",
      "content": "Jelaskan 3 aturan emas pembuatan Flyway DDL PostgreSQL sesuai standar EKSAD (7 audit columns, soft delete, epoch millisecond timestamp)."
    }
  ]
}

{
  "message": "Tolong buatkan skrip Flyway DDL PostgreSQL singkat untuk tabel procurement_request.",
  "stream": true,
  "user_id": "{{user_id}}"
}

{
  "message": "Tolong buatkan Dokumen TSD (Technical Specification Document) lengkap §1–§20 untuk microservice Svc Procurement Approval proyek {{project_name}} (tenant: {{tenant_name}}). Sertakan Stack Profile Tier-1 Quarkus Reactive RabbitMQ, port 8087, JWT RS256 via JWKS, dan package structure.",
  "user_id": "{{user_id}}"
}

{
  "message": "Tolong buatkan skrip Flyway DDL SQL V1__init_procurement_approval.sql untuk 4 tabel: purchase_request, approval_history, vendor_cache, department_cache. Pastikan 7 audit columns wajib, soft delete, BIGINT epoch millis, NUMERIC(20,4), dan 13 reserved fields opted-in untuk transactional entities.",
  "user_id": "{{user_id}}"
}

{
  "message": "Tolong buatkan Katalog API REST lengkap 15 endpoint untuk Svc Procurement Approval dengan pemetaan otorisasi RBAC @RolesAllowed(ROLE_REQUESTER, ROLE_APPROVER, ROLE_ADMIN).",
  "user_id": "{{user_id}}"
}

{
  "message": "Tolong buatkan skema RabbitMQ Event Topology (Exchange exc-procurement, Routing Keys, Queue q-procurement-submitted, DLQ) dan EKSAD Event Envelope JSON schema.",
  "user_id": "{{user_id}}"
}

{
  "message": "Tolong buatkan Dokumen STRIDE Threat Modeling lengkap 6 kategori (Spoofing, Tampering, Repudiation, Info Disclosure, DoS, Elevation of Privilege) dengan pemetaan 28 ancaman dan rencana mitigasi.",
  "user_id": "{{user_id}}"
}
